    ru: `<rect width="60" height="14" fill="#fff"/><rect y="13" width="60" height="14" fill="#0039a6"/><rect y="26" width="60" height="14" fill="#d52b1e"/>`,
    su: `<rect width="60" height="40" fill="#cc0000"/><path d="M9 8 L13 8 L11 4Z" fill="#ffd700"/><path d="M8 16 C8 11 12 9 14 10 C11 11 10 14 12 17 L16 13 L17 14 L13 18 C15 20 18 19 19 16 C20 20 15 23 11 21 L8 24 L7 23 L10 20 C8 19 8 18 8 16Z" fill="#ffd700"/>`,
    jp: `<rect width="60" height="40" fill="#fff"/><circle cx="30" cy="20" r="11" fill="#bc002d"/>`,
    un: `<rect width="60" height="40" fill="#5b92e5"/><circle cx="30" cy="20" r="10" fill="none" stroke="#fff" stroke-width="2"/><path d="M30 10 V30 M20 20 H40" stroke="#fff" stroke-width="1.4"/>`,
    cu: `${[0, 1, 2, 3, 4].map(i => `<rect y="${i * 8}" width="60" height="8" fill="${i % 2 ? '#fff' : '#002a8f'}"/>`).join('')}<path d="M0 0 L26 20 L0 40Z" fill="#cf142b"/>${star5(9, 20, 5, '#fff')}`,
    mx: `<rect width="20" height="40" fill="#006847"/><rect x="20" width="20" height="40" fill="#fff"/><rect x="40" width="20" height="40" fill="#ce1126"/><circle cx="30" cy="20" r="4" fill="#8a5a2a"/>`,
    br: `<rect width="60" height="40" fill="#009c3b"/><path d="M30 5 L55 20 L30 35 L5 20Z" fill="#ffdf00"/><circle cx="30" cy="20" r="7" fill="#002776"/>`,
    eu: `<rect width="60" height="40" fill="#003399"/>${Array.from({ length: 12 }, (_, i) => { const a = i / 12 * 2 * Math.PI; return star5(30 + 11 * Math.cos(a), 20 + 11 * Math.sin(a), 2, '#ffcc00'); }).join('')}`,
    mapu: `<rect width="60" height="13" fill="#1f4fbf"/><rect y="13" width="60" height="14" fill="#1d1d1d"/><rect y="27" width="60" height="13" fill="#2a9a4a"/><rect y="11" width="60" height="2.5" fill="#fff"/><rect y="26.5" width="60" height="2.5" fill="#fff"/><circle cx="30" cy="20" r="5" fill="#c8102e"/>`,
