    cn: `<rect width="60" height="40" fill="#de2910"/>${star5(10, 10, 6, '#ffde00')}${[[20, 4], [24, 8], [24, 14], [20, 18]].map(([x, y]) => star5(x, y, 2, '#ffde00')).join('')}`,
    vn: `<rect width="60" height="40" fill="#da251d"/>${star5(30, 20, 11, '#ffff00')}`,
