    church: o => [110, 150, `<rect x="40" y="10" width="30" height="60" fill="#e8e0cc"/><path d="M36 14 L55 -6 L74 14Z" fill="#9a3b2a"/><rect x="53" y="-20" width="4" height="16" fill="${G}"/><rect x="48" y="-15" width="14" height="4" fill="${G}"/><rect x="10" y="64" width="90" height="86" fill="#efe8d6"/><path d="M4 68 L55 36 L106 68Z" fill="#b5513a"/><path d="M42 150 L42 112 C42 98 68 98 68 112 L68 150Z" fill="#6b4a32"/><circle cx="55" cy="40" r="7" fill="#d9cfb8"/><circle cx="55" cy="40" r="5" fill="#fff" opacity=".6"/><rect x="18" y="86" width="12" height="22" rx="6" fill="#4d8cff" opacity=".7"/><rect x="80" y="86" width="12" height="22" rx="6" fill="#4d8cff" opacity=".7"/>`, { g: 1 }],
    palace: o => [180, 110, `<rect x="0" y="40" width="180" height="70" fill="#e9dfc4"/><path d="M60 40 L90 14 L120 40Z" fill="#d8caa4"/><rect x="0" y="34" width="180" height="8" fill="#d8caa4"/>${Array.from({ length: 9 }, (_, i) => `<rect x="${8 + i * 20}" y="52" width="10" height="20" rx="5" fill="#4d6fae"/><rect x="${8 + i * 20}" y="80" width="10" height="20" rx="5" fill="#4d6fae"/>`).join('')}<rect x="80" y="78" width="20" height="32" fill="#6b4a32"/><circle cx="90" cy="30" r="5" fill="${G}"/>`, { g: 1 }],
    house: o => [90, 86, `<rect x="10" y="36" width="70" height="50" fill="${o.c || '#d9b98f'}"/><path d="M2 40 L45 6 L88 40Z" fill="#a8483a"/><rect x="38" y="56" width="16" height="30" fill="#6b4a32"/><rect x="18" y="48" width="14" height="14" fill="#9fd0ff"/><rect x="60" y="48" width="14" height="14" fill="#9fd0ff"/>`, { g: 1 }],
