    conventillo: o => [160, 110, `<rect x="0" y="20" width="160" height="90" fill="#9a8a78"/><rect x="0" y="12" width="160" height="10" fill="#7a6a58"/>${Array.from({ length: 6 }, (_, i) => `<rect x="${10 + i * 25}" y="34" width="14" height="22" fill="#3a3028"/><rect x="${10 + i * 25}" y="74" width="14" height="36" fill="#4a3a2a"/>`).join('')}<path d="M0 64 L160 64" stroke="#5a4a3a" stroke-width="3"/><path d="M14 30 Q40 40 66 30 Q92 40 118 30" stroke="#ddd" stroke-width="1.2" fill="none"/><rect x="30" y="30" width="7" height="9" fill="${R}"/><rect x="70" y="31" width="8" height="10" fill="${B}"/>`, { g: 1 }],
    factory: o => [170, 130, `<rect x="0" y="60" width="170" height="70" fill="#5b5f68"/><path d="M0 60 L30 40 L30 60 L60 40 L60 60 L90 40 L90 60Z" fill="#6b707a"/><rect x="104" y="6" width="18" height="70" fill="#7a5a4a"/><rect x="136" y="18" width="16" height="58" fill="#7a5a4a"/>${Array.from({ length: 5 }, (_, i) => `<rect x="${10 + i * 32}" y="80" width="20" height="16" fill="${Y}" opacity=".8"/>`).join('')}<rect x="70" y="100" width="28" height="30" fill="#3a3d44"/><g class="smoke"><circle cx="113" cy="0" r="10" fill="#8a8a8a" opacity=".7"/><circle cx="124" cy="-10" r="12" fill="#9a9a9a" opacity=".55"/><circle cx="144" cy="10" r="9" fill="#8a8a8a" opacity=".6"/></g>`, { g: 1 }],
